static char guest_json[32768]="";static int guest_valid=0,client_offset=0;
static int guest_load(void){char*body=malloc(32768);guest_valid=0;if(!body)return 0;const char*payload="{\"action\":\"wifi.guest.status\",\"params\":{}}";if(tf_http(9460,"POST","/control",NULL,payload,body,32768)==200&&tf_control_success(body,payload)){tf_json d;if(tf_parse(&d,body)){int r=tf_key(&d,0,"result"),guests=tf_key(&d,r,"guests");if(guests>=0&&d.t[guests].type=='['){size_t n=(size_t)(d.t[r].end-d.t[r].start);if(n<sizeof guest_json){memcpy(guest_json,d.s+d.t[r].start,n);guest_json[n]=0;guest_valid=1;}}tf_free(&d);}}memset(body,0,32768);free(body);return guest_valid;}
static int guest_find(const tf_json*d,const char*section){int a=tf_key(d,0,"guests"),found=-1;if(a>=0&&d->t[a].type=='[')for(int i=a+1;i<d->t[a].next;i=d->t[i].next){char s[32];if(tf_gets(d,i,"section",s,sizeof s)&&!strcmp(s,section)){if(found>=0)return-1;found=i;}}return found;}
static int guest_form_verify(const char*payload){if(!guest_load())return 0;tf_json p,d;if(!tf_parse(&p,payload))return 0;if(!tf_parse(&d,guest_json)){tf_free(&p);return 0;}int params=tf_key(&p,0,"params");char section[32];int ok=tf_gets(&p,params,"section",section,sizeof section),i=ok?guest_find(&d,section):-1;ok=i>=0;const char*keys[]={"ssid","encryption"};for(int k=0;k<2;k++)if(tf_key(&p,params,keys[k])>=0){char wanted[128],actual[128];ok=ok&&tf_gets(&p,params,keys[k],wanted,sizeof wanted)&&tf_gets(&d,i,keys[k],actual,sizeof actual)&&!strcmp(wanted,actual);}tf_free(&p);tf_free(&d);return ok;}
static int service_mac(const char*s){if(strlen(s)!=17)return 0;for(int i=0;i<17;i++)if(i%3==2?s[i]!=':':!isxdigit((unsigned char)s[i]))return 0;return 1;}
static int service_is_wifi(const tf_json*d,int client){char band[16]="",kind[32]="";tf_gets(d,client,"band",band,sizeof band);tf_gets(d,client,"kind",kind,sizeof kind);return !strcmp(band,"2g")||!strcmp(band,"5g")||!strcmp(band,"6g")||!strcmp(kind,"wifi");}
static int service_wifi_mac(const tf_json*d,const char*mac){int a=tf_key(d,tf_key(d,0,"clients"),"list");if(a<0||d->t[a].type!='[')return 0;for(int i=a+1;i<d->t[a].next;i=d->t[i].next){char candidate[32];if(tf_gets(d,i,"mac",candidate,sizeof candidate)&&!strcasecmp(candidate,mac))return service_is_wifi(d,i);}return 0;}
static int service_blocked(const tf_json*d,const char*mac){int a=tf_key(d,tf_key(d,0,"clients"),"blocked");if(a<0||d->t[a].type!='[')return-1;for(int i=a+1;i<d->t[a].next;i=d->t[i].next){char value[32];if(!tf_string(d,i,value,sizeof value)||!service_mac(value))return-1;if(!strcasecmp(value,mac))return 1;}return 0;}
static int service_client_allowed(const tf_json*d,const char*mac,int block){char mode[64];if(!service_mac(mac)||!tf_gets(d,tf_key(d,0,"clients"),"acl_mode",mode,sizeof mode)||(strcmp(mode,"deny")&&strcmp(mode,"disable")))return 0;int blocked=service_blocked(d,mac);return block?blocked==0&&service_wifi_mac(d,mac):!strcmp(mode,"deny")&&blocked==1;}
static int service_client_recheck(const char*payload,const tf_json*d){char action[64],mac[32],params[128];if(!json_get(payload,"action",action,sizeof action))return 0;if(strcmp(action,"client.block")&&strcmp(action,"client.unblock"))return 1;return json_get(payload,"params",params,sizeof params)&&json_get(params,"mac",mac,sizeof mac)&&service_client_allowed(d,mac,!strcmp(action,"client.block"));}
static void clients_render(void){advanced_shell("连接设备");tf_json d;if(!fresh_state(&d)){ah("<div class='hint'>数据不可用</div>");goto end;}int clients=tf_key(&d,0,"clients"),a=tf_key(&d,clients,"list");char mode[64]="";tf_gets(&d,clients,"acl_mode",mode,sizeof mode);if(!strcmp(mode,"allow"))ah("<div class='hint'>当前为白名单模式，屏幕不会覆盖现有名单。</div>");else if(strcmp(mode,"deny")&&strcmp(mode,"disable"))ah("<div class='hint'>过滤模式未知，暂不允许修改设备访问限制。</div>");int count=0,shown=0;if(a>=0&&d.t[a].type=='[')for(int i=a+1;i<d.t[a].next;i=d.t[i].next,count++){if(count<client_offset||shown>=8)continue;char mac[32],name[256]="",ip[80]="",safe[2048];if(!tf_gets(&d,i,"mac",mac,sizeof mac)||!service_mac(mac))continue;tf_gets(&d,i,"name",name,sizeof name);tf_gets(&d,i,"ip",ip,sizeof ip);esc(safe,sizeof safe,*name?name:"未命名设备");ah("<div class='card'><b style='word-break:break-all'>%s</b>",safe);modem_row("IP",ip);modem_row("MAC",mac);int blocked=service_blocked(&d,mac);if(blocked>=0&&service_client_allowed(&d,mac,!blocked))ah("<a class='button secondary' href='act:client-%s:%s' style='margin-top:6px'>%s此设备</a>",blocked?"unblock":"block",mac,blocked?"解除 Wi-Fi 限制":"限制 Wi-Fi 接入");ah("</div>");shown++;}if(!count)ah("<div class='hint'>没有可显示的连接设备</div>");if(client_offset>0)ah("<a class='button secondary' href='act:clients-prev' style='margin:6px 0'>上一页</a>");if(count>client_offset+8)ah("<a class='button secondary' href='act:clients-next' style='margin:6px 0'>下一页</a>");int blocked=tf_key(&d,clients,"blocked");if(!strcmp(mode,"deny")&&blocked>=0&&d.t[blocked].type=='['){ah("<h3 style='margin:12px 0 8px'>已限制名单</h3>");for(int i=blocked+1;i<d.t[blocked].next;i=d.t[i].next){char mac[32];if(tf_string(&d,i,mac,sizeof mac)&&service_client_allowed(&d,mac,0))ah("<a class='button secondary' href='act:client-unblock:%s' style='margin-bottom:6px'>%s · 解除</a>",mac,mac);}}tf_free(&d);end:ah("</div></body></html>");}
