static void more_render(void){advanced_shell("更多设备设置");const char*actions[]={"power","guest","clients","traffic","display","wps","wifi-dual"},*labels[]={"散热与电源","访客 Wi-Fi","连接设备与限制","主卡流量管理","显示与锁屏","WPS 配对","Wi-Fi 双频合一"};for(int i=0;i<7;i++)ah("<a class='button secondary' href='act:%s' style='margin:8px 0'>%s</a>",actions[i],labels[i]);ah("<p class='note'>屏幕解锁后可操作，修改设置前会再次确认。</p></div></body></html>");}
static int service_action(const char*a){if(!strcmp(a,"more")){advanced_page=12;scroll_y=0;return 1;}if(!strcmp(a,"clients")){settings_child_parent=advanced_page==12?12:0;advanced_page=9;client_offset=0;scroll_y=0;return 1;}if(!strcmp(a,"clients-next")||!strcmp(a,"clients-prev")){client_offset+=!strcmp(a,"clients-next")?8:-8;if(client_offset<0)client_offset=0;scroll_y=0;return 1;}
 if(!strncmp(a,"client-block:",13)||!strncmp(a,"client-unblock:",15)){int block=!strncmp(a,"client-block:",13);const char*mac=a+(block?13:15);if(advanced_page!=9||!service_mac(mac)||!control_guard())return 1;tf_json d;if(!fresh_state(&d))return 1;int permitted=service_client_allowed(&d,mac,block);tf_free(&d);if(!permitted){show_notice("设备类型、名单或过滤模式已变化，未提交");return 1;}snprintf(pending,sizeof pending,"{\"action\":\"client.%s\",\"params\":{\"mac\":\"%s\"}}",block?"block":"unblock",mac);snprintf(pending_label,sizeof pending_label,"%s设备 %s 的 Wi-Fi 接入限制。限制接入会启用黑名单模式；提交后回读限制名单。",block?"设置":"解除",mac);scroll_y=0;return 1;}
 if(!strcmp(a,"guest")||!strcmp(a,"guest-refresh")){if(!strcmp(a,"guest"))settings_child_parent=(advanced_page==12||advanced_page==22)?advanced_page:0;advanced_page=11;scroll_y=0;show_busy("正在读取访客 Wi-Fi");guest_load();return 1;}
 if(!strncmp(a,"guest-edit:",11)){if(advanced_page!=11||!guest_valid)return 1;tf_json d;if(!tf_parse(&d,guest_json))return 1;int i=guest_find(&d,a+11);char ssid[128],enc[64];int ok=i>=0&&tf_bool(&d,tf_key(&d,i,"supported"))==1&&tf_gets(&d,i,"ssid",ssid,sizeof ssid)&&tf_gets(&d,i,"encryption",enc,sizeof enc)&&tf_wifi_enc_index(enc)>=0&&strlen(ssid)<=32;tf_free(&d);if(ok){form_reset();form_kind=2;form_is_guest=1;snprintf(form_section,sizeof form_section,"%s",a+11);snprintf(form_band,sizeof form_band,"%s",strstr(a+11,"2g")?"2g":"5g");snprintf(form_values[0],513,"%s",ssid);snprintf(form_values[2],513,"%s",enc);memcpy(form_original,form_values,sizeof form_values);advanced_page=6;scroll_y=0;}return 1;}
 if(!strncmp(a,"guest-toggle:",13)||!strncmp(a,"guest-time:",11)||!strncmp(a,"guest-management:",17)){if((advanced_page!=11&&!(advanced_page==6&&form_is_guest))||!guest_valid||!control_guard())return 1;if(!strncmp(a,"guest-toggle:",13)){const char*band=a+13;if(strcmp(band,"2g:0")&&strcmp(band,"2g:1")&&strcmp(band,"5g:0")&&strcmp(band,"5g:1"))return 1;snprintf(pending,sizeof pending,"{\"action\":\"wifi.guest.set\",\"params\":{\"bands\":{\"%.2s\":%s}}}",band,band[3]=='1'?"true":"false");}else{int management=!strncmp(a,"guest-management:",17);const char*v=a+(management?17:11);if(strlen(v)!=1||*v<'0'||*v>(management?'1':'4'))return 1;const int times[]={0,120,240,480,720};snprintf(pending,sizeof pending,"{\"action\":\"wifi.guest.set\",\"params\":{\"%s\":%s%d}}",management?"management_access":"active_time","",management?*v-'0':times[*v-'0']);if(management)snprintf(pending,sizeof pending,"{\"action\":\"wifi.guest.set\",\"params\":{\"management_access\":%s}}",*v=='1'?"true":"false");}snprintf(pending_label,sizeof pending_label,"修改所选访客网络设置，可能使访客连接中断；主 Wi-Fi 频段保持原有开关状态。确认后回读访客状态。");scroll_y=0;return 1;}return 0;}
static int guest_settings_verify(const char*payload){if(!guest_valid)return 0;tf_json p,d;if(!tf_parse(&p,payload))return 0;if(!tf_parse(&d,guest_json)){tf_free(&p);return 0;}int params=tf_key(&p,0,"params"),bands=tf_key(&p,params,"bands"),ok=1;const char*keys[]={"2g","5g"},*sections[]={"guest_2g","guest_5g"};for(int k=0;k<2;k++)if(tf_key(&p,bands,keys[k])>=0){int wanted=tf_bool(&p,tf_key(&p,bands,keys[k])),i=guest_find(&d,sections[k]);ok=ok&&wanted>=0&&i>=0&&tf_bool(&d,tf_key(&d,i,"enabled"))==wanted;}if(tf_key(&p,params,"management_access")>=0){int wanted=tf_bool(&p,tf_key(&p,params,"management_access"));ok=ok&&wanted>=0&&tf_bool(&d,tf_key(&d,0,"management_access"))==wanted;}if(tf_key(&p,params,"active_time")>=0){long long wanted,actual;ok=ok&&tf_int(&p,tf_key(&p,params,"active_time"),&wanted)&&tf_int(&d,tf_key(&d,0,"active_time_minutes"),&actual)&&wanted==actual;}tf_free(&p);tf_free(&d);return ok;}
/* Capture only fields being changed; a fresh read must still match the user's view. */
typedef struct {int band[2],minutes,management;} tf_guest_selection;
static int guest_settings_capture(const char*payload,tf_guest_selection*out){
 out->band[0]=out->band[1]=out->minutes=out->management=-1;if(!guest_valid)return 0;tf_json p,d;if(!tf_parse(&p,payload))return 0;if(!tf_parse(&d,guest_json)){tf_free(&p);return 0;}
 int params=tf_key(&p,0,"params"),bands=tf_key(&p,params,"bands"),ok=params>=0,count=0;const char*keys[]={"2g","5g"},*sections[]={"guest_2g","guest_5g"};
 for(int k=0;k<2;k++)if(tf_key(&p,bands,keys[k])>=0){int i=guest_find(&d,sections[k]);out->band[k]=tf_bool(&d,tf_key(&d,i,"enabled"));ok=ok&&i>=0&&tf_bool(&d,tf_key(&d,i,"supported"))==1&&out->band[k]>=0&&tf_bool(&p,tf_key(&p,bands,keys[k]))>=0;count++;}
 if(tf_key(&p,params,"management_access")>=0){out->management=tf_bool(&d,tf_key(&d,0,"management_access"));ok=ok&&out->management>=0&&tf_bool(&p,tf_key(&p,params,"management_access"))>=0;count++;}
 if(tf_key(&p,params,"active_time")>=0){long long wanted=0,current=0;ok=ok&&tf_bool(&d,tf_key(&d,0,"active_time_supported"))==1&&tf_int(&d,tf_key(&d,0,"active_time_minutes"),&current)&&current>=0&&current<=720&&tf_int(&p,tf_key(&p,params,"active_time"),&wanted)&&(wanted==0||wanted==120||wanted==240||wanted==480||wanted==720);out->minutes=(int)current;count++;}
 tf_free(&p);tf_free(&d);return ok&&count>0;
}
static int service_guest_confirm(void){if(pending[0]!='{')return 0;char action[64];if(!json_get(pending,"action",action,sizeof action)||strcmp(action,"wifi.guest.set"))return 0;if(!control_guard()){pending[0]=0;return 1;}char payload[4096],response[32768];snprintf(payload,sizeof payload,"%s",pending);pending[0]=0;tf_guest_selection before,after;int baseline=guest_settings_capture(payload,&before);show_busy("正在核对访客设置");if(!baseline||!guest_load()||!guest_settings_capture(payload,&after)||(before.band[0]!=after.band[0]||before.band[1]!=after.band[1]||before.minutes!=after.minutes||before.management!=after.management)||tf_http_cancelled||!control_guard()){show_notice("访客状态已变化、不可用或操作取消；请刷新后重试");scroll_y=0;return 1;}show_busy("正在更新访客设置");if(tf_http_cancelled||!control_guard()){show_notice("操作已取消，未修改访客设置");scroll_y=0;return 1;}int accepted=tf_http_timeout(9460,"POST","/control",NULL,payload,response,sizeof response,10000)==200&&tf_control_success(response,payload),verified=0;if(accepted){tf_json d;if(tf_parse(&d,response)){verified=tf_bool(&d,tf_key(&d,tf_key(&d,0,"result"),"verified"))==1;tf_free(&d);}}verified=verified&&guest_load()&&guest_settings_verify(payload);show_notice(verified?"后端已回读确认访客设置":"访客设置未确认；未自动重试");snprintf(verification_message,sizeof verification_message,"%s",notice);scroll_y=0;return 1;}
